WITH t AS (SELECT trace_id,call_id,min(recorded_at) at,max(server_release) release,max(elapsed_ms) FILTER(WHERE stage='brain_request') request,max(elapsed_ms) FILTER(WHERE stage='brain_first_token') token,max(elapsed_ms) FILTER(WHERE stage='brain_complete') complete,max(elapsed_ms) FILTER(WHERE stage='tts_request') tts,max(elapsed_ms) FILTER(WHERE stage='first_voiced_audio_published') audio FROM voice_turn_timings WHERE recorded_at >= '2026-10-17T16:00:00Z' AND recorded_at < '2026-10-24T16:00:00Z' GROUP BY trace_id,call_id) SELECT * FROM t WHERE audio IS NOT NULL AND token-request > 4900 ORDER BY token-request DESC LIMIT 12;
